import{_ as t,o as i,c as r,ag as o}from"./chunks/framework.DLWhSH9p.js";const u=JSON.parse('{"title":"AI Providers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-providers.md","filePath":"guide/ai-providers.md"}'),a={name:"guide/ai-providers.md"};function s(d,e,n,l,c,p){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-providers" tabindex="-1">AI Providers <a class="header-anchor" href="#ai-providers" aria-label="Permalink to &quot;AI Providers&quot;">​</a></h1><p>CRAFT Studio supports three AI providers. All can be active at once — pick per-request from the model dropdown. Keys are stored per user and managed from <strong>Profile → API keys</strong> in the sidebar.</p><h2 id="free-model" tabindex="-1">Free model <a class="header-anchor" href="#free-model" aria-label="Permalink to &quot;Free model&quot;">​</a></h2><p>Every signed-in account has access to a built-in free model for script writing, ideas, and revisions. It shows up as <strong>Free</strong> in the model picker and works without any key — useful for exploring the studio before you decide which paid provider you want to add.</p><h2 id="gemini-google" tabindex="-1">Gemini (Google) <a class="header-anchor" href="#gemini-google" aria-label="Permalink to &quot;Gemini (Google)&quot;">​</a></h2><p>Paste a Gemini key under <strong>Profile → API keys → Gemini</strong>.</p><p>Get one at <a href="https://ai.google.dev/gemini-api/docs/api-key" target="_blank" rel="noreferrer">ai.google.dev</a>.</p><p><strong>Characteristics</strong></p><ul><li>Streams responses in real time</li><li>Good for quick iterations</li><li>The free Gemini tier is usually enough to try the studio end to end</li></ul><h2 id="claude-anthropic" tabindex="-1">Claude (Anthropic) <a class="header-anchor" href="#claude-anthropic" aria-label="Permalink to &quot;Claude (Anthropic)&quot;">​</a></h2><p>Claude signs in with a <strong>long-lived token from your Claude subscription</strong>, not a paid API key. Generate one at <a href="https://claude.ai/settings/tokens" target="_blank" rel="noreferrer">claude.ai/settings/tokens</a> and paste it under <strong>Profile → API keys → Claude</strong>.</p><div class="tip custom-block"><p class="custom-block-title">No API credits needed</p><p>The token uses your existing Claude subscription. Premium accounts get the full Claude model family (Opus, Sonnet, Haiku) plus research-tool access when a token is saved.</p></div><p><strong>Characteristics</strong></p><ul><li>May use research tools (storytelling, comedy, etc.) during multi-turn generation</li><li>Responses arrive once they&#39;re complete (intermediate planning is filtered out)</li><li>Excellent for complex script writing and fact-checking</li></ul><h2 id="model-selection" tabindex="-1">Model selection <a class="header-anchor" href="#model-selection" aria-label="Permalink to &quot;Model selection&quot;">​</a></h2><p>The model dropdown appears in:</p><ul><li>The Script editor&#39;s Revise tab</li><li>AI chat</li><li>The Ideas inline context hint</li><li>The mobile app&#39;s script detail</li></ul><p>All available providers show in the same dropdown, grouped by provider. Providers that aren&#39;t set up for your account are disabled with a short reason.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Free</th><th>Gemini</th><th>Claude</th></tr></thead><tbody><tr><td>What you need</td><td>Nothing</td><td>A Gemini key</td><td>A Claude subscription</td></tr><tr><td>Streaming</td><td>Yes</td><td>Yes</td><td>No (single response)</td></tr><tr><td>Research tools</td><td>No</td><td>No</td><td>Yes</td></tr><tr><td>Best for</td><td>Trying things out, drafts</td><td>Fast iterations</td><td>Complex scripts &amp; fact-checking</td></tr></tbody></table>',20)])])}const m=t(a,[["render",s]]);export{u as __pageData,m as default};
